<script>
(() => {
const routes=window.salesReturnRoutes, init=window.salesReturnInitial;
const state={type:init.sourceType||'internal_invoice',customer:null,invoice:null,internalItems:[],sazehItems:[],newProducts:[],selectedCategories:[],selectedProducts:{},selectedVariants:new Map(),defaultWarehouse:document.getElementById('defaultWarehouse').value,summary:{},items:init.items||[]};
let customerAbort, customerRequest=0, productAbort, categoryProductAbort, customerTimer, productTimer;
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const fmt=n=>Number(n||0).toLocaleString('fa-IR');
const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const whName=id=>(init.warehouses.find(w=>String(w.id)===String(id))||{}).name||'—';
const defaultWhFor=cond=>(init.warehouses.find(w=>w.type===(cond==='damaged'?'return':'central'))||init.warehouses[0]||{}).id;
function syncSource(){state.type=$('#sourceTypeInput').value=state.type;$$('[data-source-choice]').forEach(el=>el.classList.toggle('active',el.dataset.sourceChoice===state.type));$$('[name=source_choice]').forEach(r=>r.checked=r.value===state.type);$$('.sazeh-only').forEach(el=>el.classList.toggle('d-none',state.type!=='sazeh_hesab'));$$('.internal-only,.internal-col').forEach(el=>el.classList.toggle('d-none',state.type==='sazeh_hesab'));renderItems();}
function setSource(type){if(type===state.type)return;if(state.items.length&&!confirm('با تغییر نوع برگشت، اقلام فعلی پاک می‌شوند. ادامه می‌دهید؟')){syncSource();return}state.type=type;state.invoice=null;$('#invoiceId').value='';state.items=[];syncSource();}
function hiddenInputs(it,i){const parts=[];const h=(k,v)=>parts.push(`<input type="hidden" name="items[${i}][${k}]" value="${esc(v)}">`);h('item_source',it.item_source);h('invoice_item_id',it.invoice_item_id||'');h('product_variant_id',it.product_variant_id||'');h('return_quantity',it.return_quantity||1);h('item_condition',it.item_condition||'healthy');h('destination_warehouse_id',it.destination_warehouse_id||state.defaultWarehouse||defaultWhFor(it.item_condition));h('refund_unit_price',it.refund_unit_price||0);h('purchase_price',it.purchase_price||'');h('sell_price',it.sell_price||'');if(it.new_product_payload)Object.entries(it.new_product_payload).forEach(([k,v])=>h(`new_product_payload][${k}`,v));return parts.join('')}
function rowName(it){return `${it.product_name||it.new_product_payload?.product_name||'—'} / ${it.variant_name||it.new_product_payload?.variant_name||'—'}`}
function renderItems(){const tb=$('#itemsTable tbody');tb.innerHTML='';$('#mobileItems').innerHTML='';state.items.forEach((it,i)=>{const max=state.type==='internal_invoice'?(it.returnable||1):999999;it.return_quantity=Math.max(1,Math.min(Number(it.return_quantity||1),max));it.refund_amount=it.return_quantity*Number(it.refund_unit_price||0);const tr=document.createElement('tr');tr.innerHTML=`<td>${hiddenInputs(it,i)}<strong>${esc(rowName(it))}</strong><div class="small sr-muted">${it.item_source==='new_product'?'کالای جدید؛ ساخت در ثبت نهایی':it.item_source==='existing_product'?'کالای موجود':'آیتم فاکتور'}</div></td><td>${esc(it.sku||it.barcode||it.new_product_payload?.sku||'—')}</td><td class="internal-col">${it.sold_quantity??'—'}</td><td class="internal-col">${it.previously_returned??'—'}</td><td class="internal-col">${it.returnable??'—'}</td><td><input class="form-control form-control-sm qty" data-i="${i}" type="number" min="1" max="${max}" value="${it.return_quantity}"></td><td><select class="form-select form-select-sm cond" data-i="${i}"><option value="healthy" ${it.item_condition==='healthy'?'selected':''}>سالم</option><option value="damaged" ${it.item_condition==='damaged'?'selected':''}>معیوب</option></select></td><td><select class="form-select form-select-sm wh" data-i="${i}">${init.warehouses.map(w=>`<option value="${w.id}" ${String(w.id)===String(it.destination_warehouse_id)?'selected':''}>${esc(w.name)}</option>`).join('')}</select></td><td>${state.type==='internal_invoice'?fmt(it.refund_unit_price):`<input class="form-control form-control-sm price" data-i="${i}" type="number" min="1" value="${it.refund_unit_price||0}">`}</td><td>${fmt(it.refund_amount)}</td><td><button class="btn btn-sm btn-outline-danger rm" data-i="${i}" type="button">حذف</button></td>`;tb.appendChild(tr);$('#mobileItems').insertAdjacentHTML('beforeend',`<div class="border rounded p-2 mb-2"><div class="d-flex justify-content-between"><strong>${esc(rowName(it))}</strong><button class="btn btn-sm btn-outline-danger rm" data-i="${i}" type="button">حذف</button></div><div class="small sr-muted">تعداد: ${fmt(it.return_quantity)} | مبلغ: ${fmt(it.refund_amount)} | مقصد: ${esc(whName(it.destination_warehouse_id))}</div></div>`)});$$('.internal-col').forEach(el=>el.classList.toggle('d-none',state.type==='sazeh_hesab'));summary();}
function summary(){const qty=state.items.reduce((s,i)=>s+Number(i.return_quantity||0),0),healthy=state.items.filter(i=>(i.item_condition||'healthy')==='healthy').reduce((s,i)=>s+Number(i.return_quantity||0),0),amount=state.items.reduce((s,i)=>s+Number(i.refund_amount||0),0);$('[data-sum=rows]').textContent=state.items.length;$('[data-sum=qty]').textContent=fmt(qty);$('[data-sum=healthy]').textContent=fmt(healthy);$('[data-sum=damaged]').textContent=fmt(qty-healthy);$('[data-sum=amount]').textContent=fmt(amount);$('[data-sum=warehouses]').textContent=[...new Set(state.items.map(i=>whName(i.destination_warehouse_id)))].join('، ')||'—'}
function renderCustomerStatus(html){$('#customerResults').innerHTML=html;$('#customerResults').classList.remove('d-none')}
async function searchCustomers(q=''){if(customerAbort)customerAbort.abort();const req=++customerRequest;customerAbort=new AbortController();renderCustomerStatus('<div class="p-2 sr-muted">در حال جستجو...</div>');try{const url=routes.customersSearch+(q?('?q='+encodeURIComponent(q)):'');const r=await fetch(url,{signal:customerAbort.signal});if(req!==customerRequest)return;const data=await r.json();const rows=data.data||data.results||[];renderCustomerStatus(rows.length?rows.map(c=>`<div class="sr-result" role="option" tabindex="0" data-id="${c.id}" data-name="${esc(c.name||c.text)}" data-mobile="${esc(c.mobile||'')}" data-code="${esc(c.customer_code||c.code||'')}"><strong>${esc(c.name||c.text)}</strong><div class="small sr-muted">${esc(c.mobile||'بدون موبایل')} | کد: ${esc(c.customer_code||c.code||c.id)}</div></div>`).join(''):'<div class="p-2 sr-muted">مشتری‌ای پیدا نشد.</div>')}catch(e){if(e.name!=='AbortError')renderCustomerStatus('<div class="p-2 text-danger">دریافت مشتریان با خطا مواجه شد.</div>')}}
function selectCustomer(el){const changed=$('#customerId').value!==el.dataset.id;$('#customerId').value=el.dataset.id;state.customer={id:el.dataset.id,name:el.dataset.name,mobile:el.dataset.mobile,code:el.dataset.code};$('#customerSearch').value=el.dataset.name;$('#selectedCustomerLabel').textContent=`${el.dataset.name} | ${el.dataset.mobile||'بدون موبایل'} | کد: ${el.dataset.code}`;$('#customerResults').classList.add('d-none');if(changed){$('#invoiceId').value='';state.invoice=null;state.items=[];renderItems();loadInvoices();}}
async function loadInvoices(){const id=$('#customerId').value;if(!id)return;const r=await fetch(routes.customerInvoices.replace('__CUSTOMER__',id));const data=await r.json();$('#invoiceSelect').innerHTML='<option value="">انتخاب فاکتور</option>'+(data.invoices||[]).map(inv=>`<option value="${inv.id}">${esc(inv.number)} | ${esc(inv.date)} | ${esc(inv.status_label)} | ${fmt(inv.total)} | ${inv.items_count} قلم</option>`).join('');if(init.invoiceId)$('#invoiceSelect').value=init.invoiceId}
async function loadInvoiceItems(){const inv=$('#invoiceId').value;if(!inv){alert('ابتدا فاکتور را انتخاب کنید.');return}const r=await fetch(routes.invoiceItems.replace('__INVOICE__',inv)+'?customer_id='+encodeURIComponent($('#customerId').value));if(!r.ok){alert((await r.json()).message||'خطا');return}const data=await r.json();$('#invoiceItemsBody').innerHTML=(data.items||[]).map(it=>`<tr class="${it.disabled?'table-secondary':''}" data-text="${esc((it.product_name||'')+' '+(it.variant_name||'')+' '+(it.sku||''))}"><td><input type="checkbox" class="invoice-pick" ${it.disabled||state.items.some(x=>x.invoice_item_id===it.invoice_item_id)?'disabled':''} data-item='${esc(JSON.stringify(it))}'></td><td>${esc(it.product_name||'—')}</td><td>${esc(it.variant_name||'—')}</td><td>${esc(it.sku||it.barcode||'—')}</td><td>${it.quantity}</td><td>${it.previously_returned}</td><td>${it.returnable}</td><td>${fmt(it.unit_price)}</td><td>${it.disabled?'قابل برگشت ندارد':'قابل انتخاب'}</td></tr>`).join('')}
async function loadCategories(parentId=null){const url=routes.categories+(parentId?('?parent_id='+parentId):'');const r=await fetch(url);const data=await r.json();$('#categoryResults').innerHTML=(data.data||[]).map(c=>`<button type="button" class="list-group-item list-group-item-action cat-pick" data-id="${c.id}" data-name="${esc(c.name)}" data-code="${esc(c.code||'')}"><strong>${esc(c.name)}</strong><div class="small sr-muted">${c.code?('کد '+esc(c.code)+' | '):''}${c.products_count} کالا</div></button>`).join('')||'<div class="sr-muted p-2">زیردسته‌ای وجود ندارد؛ محصولات همین دسته را ببینید.</div>'}
async function loadCategoryProducts(q=''){const cat=state.selectedCategories.at(-1);if(!cat)return;if(categoryProductAbort)categoryProductAbort.abort();categoryProductAbort=new AbortController();const r=await fetch(routes.categoryProducts.replace('__CATEGORY__',cat.id)+(q?('?q='+encodeURIComponent(q)):''),{signal:categoryProductAbort.signal});const data=await r.json();$('#categoryProductResults').innerHTML=(data.data||[]).map(p=>`<button type="button" class="list-group-item list-group-item-action product-select" data-id="${p.id}"><strong>${esc(p.name)}</strong><div class="small sr-muted">${esc(p.code||'بدون کد')} | ${esc(p.category||'بدون دسته')} | ${p.variants_count} تنوع ${p.is_active?'':' | غیرفعال'} ${p.sales_enabled?'':' | فروش غیرفعال'}</div></button>`).join('')||'<div class="p-2 sr-muted">محصولی یافت نشد.</div>'}
async function loadProductVariants(productId){const r=await fetch(routes.productVariants.replace('__PRODUCT__',productId));const data=await r.json();const product=data.product||{};state.selectedProducts[productId]=product;$('#variantCheckboxes').innerHTML=`<div class="mb-2"><strong>${esc(product.name||'محصول')}</strong><div class="small sr-muted">کد: ${esc(product.code||'—')}</div></div>`+(data.variants||[]).map(v=>{const key=String(v.id), checked=state.selectedVariants.has(key);return `<label class="d-block border rounded p-2 mb-1 ${checked?'bg-light':''}"><input type="checkbox" class="form-check-input ms-1 variant-pick" data-product-id="${productId}" data-product-name="${esc(product.name||'')}" data-variant='${esc(JSON.stringify(v))}' ${checked?'checked':''}> <strong>${esc(v.name||'تنوع اصلی')}</strong><div class="small sr-muted">طرح/مدل: ${esc(v.variety_name||'—')} | SKU: ${esc(v.sku||'—')} | موجودی: ${fmt(v.stock)} | خرید: ${fmt(v.buy_price)} | فروش: ${fmt(v.sell_price)} ${v.is_active?'':' | غیرفعال'} ${v.sales_enabled?'':' | فروش غیرفعال'}</div></label>`}).join('')+`<div class="sticky-bottom bg-white border-top pt-2 mt-2"><span id="variantSelectedCount">${state.selectedVariants.size}</span> تنوع انتخاب‌شده <button type="button" class="btn btn-primary btn-sm float-start" id="addPickedVariants">افزودن به برگشتی</button></div>`}
async function searchProducts(q){if(productAbort)productAbort.abort();if(q.length<2){$('#productResults').innerHTML='<div class="p-2 sr-muted">برای جستجو حداقل ۲ کاراکتر وارد کنید.</div>';return}productAbort=new AbortController();const r=await fetch(routes.productsSearch+'?q='+encodeURIComponent(q),{signal:productAbort.signal});const data=await r.json();$('#productResults').innerHTML=(data.results||[]).map(p=>`<button type="button" class="list-group-item list-group-item-action product-select" data-id="${p.id}"><strong>${esc(p.text)}</strong><div class="small sr-muted">${esc(p.category||'بدون دسته')} | SKU: ${esc(p.sku||'—')} | موجودی: ${fmt(p.stock)} ${p.is_active?'':' | غیرفعال'} ${p.sales_enabled?'':' | فروش غیرفعال'}</div></button>`).join('')||'<div class="p-2 sr-muted">نتیجه‌ای یافت نشد.</div>'}
function addSelectedVariants(){let added=0;state.selectedVariants.forEach(({variant,productId,productName})=>{if(state.items.some(i=>String(i.product_variant_id)===String(variant.id)))return;state.items.push({item_source:'existing_product',product_id:productId,product_variant_id:variant.id,product_name:productName,variant_name:variant.name,sku:variant.sku,barcode:variant.barcode,return_quantity:1,item_condition:'healthy',destination_warehouse_id:state.defaultWarehouse||defaultWhFor('healthy'),refund_unit_price:0,refund_amount:0,purchase_price:variant.buy_price,sell_price:variant.sell_price});added++;});renderItems();if(added)bootstrap.Modal.getInstance($('#sazehItemsModal'))?.hide();else alert('تنوع جدیدی برای افزودن وجود ندارد یا موارد تکراری هستند.')}
function updatePreview(){const designs=$$('#designRows .design-name').map(i=>i.value).filter(Boolean);const models=$$('.model-check:checked').map(i=>i.dataset.name);const count=Math.max(1,designs.length||($('#npHasDesign')?.checked?0:1))*Math.max(1,models.length||($('#npHasModel')?.checked?0:1));$('#npProductCodePreview') && ($('#npProductCodePreview').textContent=($('#npCategory')?.selectedOptions[0]?.dataset.code||'--')+'0000');$('#npVariantCodePreview') && ($('#npVariantCodePreview').textContent='کد نهایی در Backend تولید می‌شود');}
$$('[name=source_choice]').forEach(r=>r.addEventListener('change',e=>setSource(e.target.value)));$('#customerSearch').addEventListener('focus',()=>searchCustomers(''));$('#customerSearch').addEventListener('input',e=>{clearTimeout(customerTimer);customerTimer=setTimeout(()=>searchCustomers(e.target.value),300)});$('#customerResults').addEventListener('click',e=>{const el=e.target.closest('.sr-result');if(el)selectCustomer(el)});$('#refreshCustomers').onclick=()=>{state.customer=null;$('#customerSearch').value='';searchCustomers('')};$('#invoiceSelect').addEventListener('change',e=>{$('#invoiceId').value=e.target.value;state.invoice=e.target.value;state.items=[];renderItems()});$('#openAddItem').onclick=()=>{if(state.type==='internal_invoice'){loadInvoiceItems().then(()=>new bootstrap.Modal($('#internalItemsModal')).show())}else{loadCategories(null);new bootstrap.Modal($('#sazehItemsModal')).show()}};$('#addSelectedInvoiceItems').onclick=()=>{$$('.invoice-pick:checked').forEach(cb=>{const it=JSON.parse(cb.dataset.item);if(state.items.some(x=>x.invoice_item_id===it.invoice_item_id))return;state.items.push({item_source:'invoice_item',invoice_item_id:it.invoice_item_id,product_id:it.product_id,product_variant_id:it.variant_id,product_name:it.product_name,variant_name:it.variant_name,sku:it.sku,barcode:it.barcode,sold_quantity:it.quantity,previously_returned:it.previously_returned,returnable:it.returnable,return_quantity:1,item_condition:'healthy',destination_warehouse_id:state.defaultWarehouse||defaultWhFor('healthy'),refund_unit_price:it.unit_price,refund_amount:it.unit_price})});renderItems();bootstrap.Modal.getInstance($('#internalItemsModal')).hide()};$('#invoiceItemFilter').addEventListener('input',e=>{$$('#invoiceItemsBody tr').forEach(tr=>tr.classList.toggle('d-none',!tr.dataset.text.includes(e.target.value)))});$('#categoryResults')?.addEventListener('click',e=>{const el=e.target.closest('.cat-pick');if(!el)return;state.selectedCategories.push({id:el.dataset.id,name:el.dataset.name});$('#categoryPath').textContent=state.selectedCategories.map(c=>c.name).join(' > ');loadCategories(el.dataset.id);loadCategoryProducts();$('#variantCheckboxes').textContent='محصول را انتخاب کنید.'});$('#categoryProductSearch')?.addEventListener('input',e=>{clearTimeout(productTimer);productTimer=setTimeout(()=>loadCategoryProducts(e.target.value),300)});$('#productSearch')?.addEventListener('input',e=>{clearTimeout(productTimer);productTimer=setTimeout(()=>searchProducts(e.target.value),300)});document.addEventListener('click',e=>{const ps=e.target.closest('.product-select');if(ps)loadProductVariants(ps.dataset.id);if(e.target.id==='addPickedVariants')addSelectedVariants();if(e.target.classList.contains('rm')){state.items.splice(Number(e.target.dataset.i),1);renderItems()}});document.addEventListener('change',e=>{if(e.target.classList.contains('variant-pick')){const v=JSON.parse(e.target.dataset.variant), key=String(v.id);e.target.checked?state.selectedVariants.set(key,{variant:v,productId:e.target.dataset.productId,productName:e.target.dataset.productName}):state.selectedVariants.delete(key);$('#variantSelectedCount')&&($('#variantSelectedCount').textContent=state.selectedVariants.size)}if(e.target.classList.contains('cond')){const it=state.items[Number(e.target.dataset.i)];it.item_condition=e.target.value;it.destination_warehouse_id=defaultWhFor(e.target.value);renderItems()}if(e.target.classList.contains('wh')){state.items[Number(e.target.dataset.i)].destination_warehouse_id=e.target.value;renderItems()}});document.addEventListener('input',e=>{if(e.target.classList.contains('qty')){state.items[Number(e.target.dataset.i)].return_quantity=Number(e.target.value);renderItems()}if(e.target.classList.contains('price')){state.items[Number(e.target.dataset.i)].refund_unit_price=Number(e.target.value);renderItems()}});$('#defaultWarehouse').addEventListener('change',e=>{state.defaultWarehouse=e.target.value});$('#clearForm').onclick=()=>{if(confirm('فرم پاک شود؟')){state.items=[];renderItems()}};$('#applyButton').onclick=e=>{if(!confirm('ثبت نهایی موجودی و بستانکاری مشتری را تغییر می‌دهد. ادامه می‌دهید؟'))e.preventDefault()};syncSource();if(init.customerId)loadInvoices();renderItems();
})();
</script>
@endsection
